    if sign == "-":
        for i in range(len(expression)):
            # Invert the sign if the 'sign' is '-'
            if arr[i] == "+":
                arr[i] = "-"
            elif arr[i] == "-":
                arr[i] = "+"
    # If the first characters is not a sign, it is a '+' and we need to 
