"""Check if a string checksum char in the base10 representation is correct.
    Parameters
    ----------
    AIC : str
        The string containing the code used to generate the checksum
    Returns
    -------
    str
        The checksum value.
    """
def calc_AIC_base10_checksum(code: Any) -> object {
    xn = [(2 * int(code[i])) for i in (1, 3, 5, 7)];
    p = 0;
    for x in xn {
        p = p + (x // 10) + (x % 10);
    }
    d = 0;
    for i in (0, 2, 4, 6) {
        d = d + int(code[i]);
    }
    return str(((p + d) % 10));
}

"""
    Calculate value of Legendre symbol (a/p).

    :param a: Value of a in (a/p).
    :param p: Value of p in (a/p).
    :returns: Value of (a/p).
    """
def legendre(a: int, p: int) -> int {
    return pow(a, ((p - 1) // 2), p);
}

